class Solution { private static class Fenwick{int[] tree;Fenwick(int n){tree=new int[n+1];}void add(int index){for(;index<tree.length;index+=index&-index)tree[index]++;}int query(int index){int sum=0;for(;index>0;index-=index&-index)sum+=tree[index];return sum;}}public int createSortedArray(int[] instructions){final int MOD=1_000_000_007;Fenwick fenwick=new Fenwick(Arrays.stream(instructions).max().getAsInt());long cost=0;for(int i=0;i<instructions.length;i++){int value=instructions[i],less=fenwick.query(value-1),greater=i-fenwick.query(value);cost=(cost+Math.min(less,greater))%MOD;fenwick.add(value);}return (int)cost;} }
